// NER service for BMD Go - extracts named entities from OCR text.
// Built around a DistilBERT-german-cased model exported to ONNX with
// dynamic int8 quantization. WordPiece vocab (~234 KB) and the BIO
// label table are baked into this file as constants, so only this Dart
// file plus the ner.onnx asset are needed in the app.

import 'dart:convert';
import 'dart:typed_data';

import 'package:flutter/services.dart';
import 'package:onnxruntime/onnxruntime.dart';

class NEREntitySpan {
  final String type;     // BIO entity type, e.g. "PATIENT", "INV_NR"
  final String text;     // substring from original text
  final int start;       // inclusive char offset
  final int end;         // exclusive char offset

  NEREntitySpan({
    required this.type,
    required this.text,
    required this.start,
    required this.end,
  });

  Map<String, dynamic> toJson() =>
      {'type': type, 'text': text, 'start': start, 'end': end};
}

class NERResult {
  /// German snake_case key -> extracted text, e.g. {"patient": "Hans Maier"}
  final Map<String, String> felder;
  final List<NEREntitySpan> spans;
  final String rawText;
  NERResult({required this.felder, required this.spans, required this.rawText});
}

class MLServiceNER {
  late OrtSession _session;
  late Map<String, int> _vocab;
  bool _isInitialized = false;

  static const int _padId = 0;
  static const int _unkId = 101;
  static const int _clsId = 102;
  static const int _sepId = 103;
  static const int _maxLength = 256;
  static const int _maxWordChars = 100;

  Future<void> initialize() async {
    if (_isInitialized) return;

    // Decode embedded vocab (base64 of vocab.txt, one wordpiece per line)
    final vocabBytes = base64.decode(_VOCAB_B64);
    final vocabText = utf8.decode(vocabBytes);
    _vocab = <String, int>{};
    int idx = 0;
    for (final line in const LineSplitter().convert(vocabText)) {
      _vocab[line] = idx++;
    }

    // Load ONNX model
    final modelData = await rootBundle.load('assets/models/ner.onnx');
    final sessionOptions = OrtSessionOptions();
    _session = OrtSession.fromBuffer(modelData.buffer.asUint8List(), sessionOptions);

    _isInitialized = true;
  }

  Future<NERResult> extract(String text) async {
    if (!_isInitialized) {
      throw Exception('NER not initialized - call initialize() first');
    }

    // 1. Basic tokenize (whitespace + punctuation split) with char offsets
    final words = _basicTokenize(text);

    // 2. Group adjacent words (no whitespace gap) into "logical words".
    //    Trained with is_split_into_words=True, so date pieces like
    //    "01.05.2024" share one logical word.
    final groupOfWord = _groupAdjacent(words);

    // 3. WordPiece each word
    final subwords = _wordPieceTokenize(words);

    // 4. Build [CLS] body [SEP], pad to _maxLength
    final maxBody = _maxLength - 2;
    final body = subwords.length > maxBody ? subwords.sublist(0, maxBody) : subwords;
    final inputIds = <int>[_clsId];
    final groupIdxPerToken = <int>[-1];
    for (final sw in body) {
      inputIds.add(sw.id);
      groupIdxPerToken.add(groupOfWord[sw.wordIndex]);
    }
    inputIds.add(_sepId);
    groupIdxPerToken.add(-1);

    final actualLen = inputIds.length;
    final attentionMask = List<int>.filled(_maxLength, 0);
    for (int i = 0; i < actualLen; i++) {
      attentionMask[i] = 1;
    }
    while (inputIds.length < _maxLength) {
      inputIds.add(_padId);
      groupIdxPerToken.add(-1);
    }

    // 5. Run ONNX
    final inputIdsTensor = OrtValueTensor.createTensorWithDataList(
      Int64List.fromList(inputIds), [1, _maxLength],
    );
    final attentionMaskTensor = OrtValueTensor.createTensorWithDataList(
      Int64List.fromList(attentionMask), [1, _maxLength],
    );
    final runOptions = OrtRunOptions();
    final outputs = await _session.runAsync(runOptions, <String, OrtValue>{
      'input_ids': inputIdsTensor,
      'attention_mask': attentionMaskTensor,
    });
    if (outputs == null || outputs.isEmpty) {
      throw Exception('NER produced no outputs');
    }

    // 6. Argmax per token, tag for each logical group = first subword's tag
    final raw = outputs[0]!.value as List;
    final List seq = raw.first as List;

    // Group spans (char offsets)
    final groupSpans = <_GroupSpan>[];
    int curG = -1;
    for (int wi = 0; wi < words.length; wi++) {
      final g = groupOfWord[wi];
      if (g != curG) {
        groupSpans.add(_GroupSpan(words[wi].start, words[wi].end));
        curG = g;
      } else {
        groupSpans.last.end = words[wi].end;
      }
    }

    final groupTags = <int, String>{};
    final seenGroups = <int>{};
    for (int t = 0; t < seq.length; t++) {
      final g = groupIdxPerToken[t];
      if (g < 0 || seenGroups.contains(g)) continue;
      seenGroups.add(g);

      final tokLogits = seq[t] as List;
      int best = 0;
      double bestVal = (tokLogits[0] as num).toDouble();
      for (int i = 1; i < tokLogits.length; i++) {
        final v = (tokLogits[i] as num).toDouble();
        if (v > bestVal) {
          bestVal = v;
          best = i;
        }
      }
      groupTags[g] = _idToLabel[best] ?? 'O';
    }

    // 7. BIO -> entity spans
    final spans = <NEREntitySpan>[];
    String? curType;
    int? curStart;
    int? curEnd;

    void flush() {
      if (curType != null && curStart != null && curEnd != null) {
        spans.add(NEREntitySpan(
          type: curType!,
          text: text.substring(curStart!, curEnd!),
          start: curStart!,
          end: curEnd!,
        ));
      }
      curType = null;
      curStart = null;
      curEnd = null;
    }

    for (int g = 0; g < groupSpans.length; g++) {
      final tag = groupTags[g] ?? 'O';
      final gs = groupSpans[g];
      if (tag == 'O') {
        flush();
      } else if (tag.startsWith('B-')) {
        flush();
        curType = tag.substring(2);
        curStart = gs.start;
        curEnd = gs.end;
      } else if (tag.startsWith('I-')) {
        final et = tag.substring(2);
        if (curType == et) {
          curEnd = gs.end;
        } else {
          flush();
          curType = et;
          curStart = gs.start;
          curEnd = gs.end;
        }
      }
    }
    flush();

    // 8. Aggregate to German snake_case field map
    final felder = <String, String>{};
    for (final span in spans) {
      final key = _normalizeFieldName(span.type);
      if (felder.containsKey(key)) {
        felder[key] = '${felder[key]!} ${span.text}';
      } else {
        felder[key] = span.text;
      }
    }

    return NERResult(felder: felder, spans: spans, rawText: text);
  }

  bool get isInitialized => _isInitialized;
  void dispose() => _session.release();

  // ---------------------------------------------------------------------------
  // Tokenization helpers
  // ---------------------------------------------------------------------------

  List<_WordSpan> _basicTokenize(String text) {
    final spans = <_WordSpan>[];
    final buf = StringBuffer();
    int wordStart = -1;

    for (int i = 0; i < text.length; i++) {
      final ch = text.codeUnitAt(i);
      final isWS = ch == 0x20 || ch == 0x09 || ch == 0x0A || ch == 0x0D ||
          ch == 0x00A0 || ch == 0x2028 || ch == 0x2029;
      final isPunct = _isPunctuation(ch);

      if (isWS) {
        if (buf.isNotEmpty) {
          spans.add(_WordSpan(buf.toString(), wordStart, i));
          buf.clear();
        }
        wordStart = -1;
      } else if (isPunct) {
        if (buf.isNotEmpty) {
          spans.add(_WordSpan(buf.toString(), wordStart, i));
          buf.clear();
        }
        spans.add(_WordSpan(text[i], i, i + 1));
        wordStart = -1;
      } else {
        if (wordStart < 0) wordStart = i;
        buf.write(text[i]);
      }
    }
    if (buf.isNotEmpty) {
      spans.add(_WordSpan(buf.toString(), wordStart, text.length));
    }
    return spans;
  }

  List<int> _groupAdjacent(List<_WordSpan> words) {
    final groups = List<int>.filled(words.length, 0);
    int g = 0;
    for (int i = 0; i < words.length; i++) {
      if (i > 0 && words[i].start != words[i - 1].end) {
        g++;
      }
      groups[i] = g;
    }
    return groups;
  }

  bool _isPunctuation(int ch) {
    return (ch >= 33 && ch <= 47) ||
        (ch >= 58 && ch <= 64) ||
        (ch >= 91 && ch <= 96) ||
        (ch >= 123 && ch <= 126);
  }

  List<_Subword> _wordPieceTokenize(List<_WordSpan> words) {
    final result = <_Subword>[];
    for (int wi = 0; wi < words.length; wi++) {
      final word = words[wi].text;
      if (word.length > _maxWordChars) {
        result.add(_Subword(_unkId, wi));
        continue;
      }
      bool bad = false;
      int start = 0;
      final subIds = <int>[];
      while (start < word.length) {
        int end = word.length;
        int? curId;
        while (start < end) {
          var sub = word.substring(start, end);
          if (start > 0) sub = '##$sub';
          final id = _vocab[sub];
          if (id != null) {
            curId = id;
            break;
          }
          end--;
        }
        if (curId == null) {
          bad = true;
          break;
        }
        subIds.add(curId);
        start = end;
      }
      if (bad || subIds.isEmpty) {
        result.add(_Subword(_unkId, wi));
      } else {
        for (final id in subIds) {
          result.add(_Subword(id, wi));
        }
      }
    }
    return result;
  }

  // ---------------------------------------------------------------------------
  // BIO entity type -> German snake_case key for the JSON output
  // ---------------------------------------------------------------------------

  String _normalizeFieldName(String entity) {
    const aliases = <String, String>{
      // Arztbestätigung
      'PATIENT': 'patient',
      'DOCTOR': 'arzt',
      'FACILITY': 'einrichtung',
      'ADDRESS': 'einrichtungsadresse',
      'DATE': 'datum',
      'TIME': 'uhrzeit',
      'DURATION': 'dauer_minuten',
      // Kassenbeleg / Reisekosten
      'VENDOR': 'haendler',
      'VADDRESS': 'haendleradresse',
      'AMOUNT': 'betrag',
      'CURRENCY': 'waehrung',
      'VAT_RATE': 'mwst_satz',
      'VAT_AMOUNT': 'mwst_betrag',
      'CATEGORY': 'kategorie',
      'DESC': 'beschreibung',
      'RECEIPT_NUM': 'belegnummer',
      // Lieferschein
      'DELNR': 'lieferscheinnummer',
      'DELDATE': 'lieferdatum',
      'SENDER': 'absender',
      'SADDR': 'absenderadresse',
      'RECIP': 'empfaenger',
      'RADDR': 'empfaengeradresse',
      'ORDNR': 'bestellnummer',
      'ITEM_DESC': 'artikelbezeichnung',
      'ITEM_QTY': 'artikelmenge',
      'ITEM_UNIT': 'artikeleinheit',
      'WEIGHT': 'gesamtgewicht',
      // Rechnung
      'INV_NR': 'rechnungsnummer',
      'INV_DATE': 'rechnungsdatum',
      'DUE_DATE': 'faelligkeitsdatum',
      'UID': 'uid',
      'BILL_TO': 'rechnungsempfaenger',
      'SHIP_TO': 'lieferanschrift',
      'NET': 'nettobetrag',
      'TOTAL': 'gesamtbetrag',
      // Pflegebestätigung
      'RELATION': 'verwandtschaftsverhaeltnis',
      'START_DATE': 'startdatum',
      'END_DATE': 'enddatum',
      'INSURANCE': 'krankenversicherung',
      // Stammdatenänderung
      'PERSON': 'name',
      'ID_NR': 'sv_nummer',
      'OLD_ADDR': 'alte_adresse',
      'NEW_ADDR': 'neue_adresse',
      'CHANGE_DATE': 'aenderungsdatum',
    };
    return aliases[entity] ?? entity.toLowerCase();
  }

  // ---------------------------------------------------------------------------
  // Embedded BIO label table (66 tags, id -> tag string)
  // ---------------------------------------------------------------------------

