    1: 'B-PATIENT',
    2: 'I-PATIENT',
    3: 'B-DOCTOR',
    4: 'I-DOCTOR',
    5: 'B-FACILITY',
    6: 'I-FACILITY',
    7: 'B-ADDRESS',
    8: 'I-ADDRESS',
    9: 'B-DATE',
    10: 'I-DATE',
    11: 'B-TIME',
    12: 'I-TIME',
    13: 'B-DURATION',
    14: 'B-VENDOR',
    15: 'I-VENDOR',
    16: 'B-VADDRESS',
    17: 'I-VADDRESS',
    18: 'B-AMOUNT',
    19: 'B-CURRENCY',
    20: 'B-VAT_RATE',
    21: 'B-VAT_AMOUNT',
    22: 'B-CATEGORY',
    23: 'B-DESC',
    24: 'I-DESC',
    25: 'B-RECEIPT_NUM',
    26: 'B-DELNR',
    27: 'B-DELDATE',
    28: 'B-SENDER',
    29: 'I-SENDER',
    30: 'B-SADDR',
    31: 'I-SADDR',
    32: 'B-RECIP',
    33: 'I-RECIP',
    34: 'B-RADDR',
    35: 'I-RADDR',
    36: 'B-ORDNR',
    37: 'B-ITEM_DESC',
    38: 'I-ITEM_DESC',
    39: 'B-ITEM_QTY',
    40: 'B-ITEM_UNIT',
    41: 'B-WEIGHT',
    42: 'I-WEIGHT',
    43: 'B-INV_NR',
    44: 'B-INV_DATE',
    45: 'B-DUE_DATE',
    46: 'B-UID',
    47: 'B-BILL_TO',
    48: 'I-BILL_TO',
    49: 'B-SHIP_TO',
    50: 'I-SHIP_TO',
    51: 'B-NET',
    52: 'B-TOTAL',
    53: 'B-RELATION',
    54: 'B-START_DATE',
    55: 'B-END_DATE',
    56: 'B-INSURANCE',
    57: 'I-INSURANCE',
    58: 'B-PERSON',
    59: 'I-PERSON',
    60: 'B-ID_NR',
    61: 'B-OLD_ADDR',
    62: 'I-OLD_ADDR',
    63: 'B-NEW_ADDR',
    64: 'I-NEW_ADDR',
    65: 'B-CHANGE_DATE',
  };

